public void runOperation(MET_POReceiptSelectionContract _contract)
{
    Query query = _contract.getQuery();
    QueryRun qr = new QueryRun(query);

    Map poMap = new Map(Types::String, Types::String);
    PurchTable purchTable;

    // Collect POs based on query + Deliver Now = ALL
    while (qr.next())
    {
        purchTable = qr.get(tableNum(PurchTable));

        if (this.isDeliverNowAll(purchTable))
        {
            poMap.insert(purchTable.PurchId, purchTable.PurchId);
        }
    }

    this.createBatchTasks(poMap, _contract.parmBatchSize());
}

private boolean isDeliverNowAll(PurchTable _purchTable)
{
    PurchLine purchLine;

    while select purchLine
        where purchLine.PurchId == _purchTable.PurchId
    {
        if (!(purchLine.RemainPurchPhysical > 0 &&
              purchLine.PurchQty == purchLine.RemainPurchPhysical))
        {
            return false;
        }
    }
    return true;
}

private void createBatchTasks(Map _poMap, int _batchSize)
{
    MapEnumerator me = _poMap.getEnumerator();
    container batchContainer;
    int purchCount = 0;
    BatchHeader header = BatchHeader::construct();

    if (_batchSize <= 0)
    {
        throw error("@MET:METPOReceiptBatchErr");
    }

    header.parmCaption("@MET:METPOReceiptBatch");

    while (me.moveNext())
    {
        batchContainer += [me.currentKey()];
        purchCount++;

        if (purchCount >= _batchSize)
        {
            this.addTask(header, batchContainer);
            batchContainer = conNull();
            purchCount = 0;
        }
    }

    if (conLen(batchContainer))
    {
        this.addTask(header, batchContainer);
    }

    header.save();
}

private void addTask(BatchHeader _header, container _purchIds)
{
    SysOperationServiceController controller = new SysOperationServiceController();
    controller.parmClassName(classStr(MET_POReceiptService));
    controller.parmMethodName(methodStr(MET_POReceiptService, processPO));
    controller.parmDialogCaption(strFmt("@MET:METPOReceiptMsg", con2StrUnlimited(_purchIds, ",")));
    Args args = new Args();
    MET_POReceiptWorkerContract workerContract = controller.getDataContractObject() as MET_POReceiptWorkerContract;
    workerContract.parmPurchIds(_purchIds);

    _header.addTask(controller);
}
